// Entry point for both Workers. The same build runs as the public site and as the staff site;
// SITE_MODE decides which routes answer.
// Generated by `opennextjs-cloudflare build`, so it only exists after a build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from './.open-next/worker.js'

const STAFF_ROUTES = /^\/(admin|api|teach|svc\/staff)(\/|$)/
const PUBLIC_PAGES = /^\/(en|ar)(\/|$)/

type Env = CloudflareEnv & { SITE_MODE?: string; JOBS_SECRET?: string; ADMIN_URL?: string; PUBLIC_URL?: string }

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url)
    const { pathname } = url
    if (env.SITE_MODE === 'public' && STAFF_ROUTES.test(pathname)) {
      return new Response('Not found', { status: 404 })
    }
    // The admin Worker's address opens the staff desk; public pages live on the public Worker.
    if (env.SITE_MODE === 'admin') {
      if (pathname === '/') return Response.redirect(new URL('/admin', url), 302)
      if (PUBLIC_PAGES.test(pathname) && env.PUBLIC_URL) {
        return Response.redirect(new URL(pathname + url.search, env.PUBLIC_URL), 302)
      }
    }
    return handler.fetch(request, env, ctx)
  },

  // Cron trigger (admin Worker only): publishes scheduled newsletters and tidies up.
  async scheduled(_event, env, ctx) {
    if (env.SITE_MODE !== 'admin' || !env.JOBS_SECRET) return
    const url = new URL('/svc/staff/jobs', env.ADMIN_URL ?? 'https://admin.internal')
    const res = await handler.fetch(new Request(url, { method: 'POST', headers: { 'x-jobs-secret': env.JOBS_SECRET } }), env, ctx)
    console.log(JSON.stringify({ job: 'scheduled', status: res.status, result: await res.text() }))
  },
} satisfies ExportedHandler<Env>
